// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  random,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Anton');

const { fontFamily } = loadFont();



export type ManifestoPosterProps = Record<string, any>;

const Scribble = ({
  index,
  frame,
  fps,
  progress,
  color,
}: {
  index: number;
  frame: number;
  fps: number;
  progress: number;
  color: string;
}) => {
  // Generate random stable properties for this scribble
  const seed = `scribble-${index}`;
  const startX = interpolate(random(`${seed}-x`), [0, 1], [-400, 400]);
  const startY = interpolate(random(`${seed}-y`), [0, 1], [-400, 400]);

  // Jitter effect - chaotic movement
  const jitterX =
    interpolate(
      frame % 12,
      [0, 3, 6, 9, 12],
      [0, 10 * random(`${seed}-jx1`), -10 * random(`${seed}-jx2`), 5, 0]
    ) * (1 - progress); // Jitter stops as it converges

  const jitterY =
    interpolate(
      frame % 10,
      [0, 5, 10],
      [0, 15 * random(`${seed}-jy1`), -15 * random(`${seed}-jy2`)]
    ) * (1 - progress);

  // Converge to center (0,0)
  const x = interpolate(progress, [0, 1], [startX + jitterX, 0], {
    easing: Easing.in(Easing.exp),
  });
  const y = interpolate(progress, [0, 1], [startY + jitterY, 0], {
    easing: Easing.in(Easing.exp),
  });

  const scale = interpolate(progress, [0, 0.9, 1], [1, 1, 0]);
  const rot = random(`${seed}-rot`) * 360 + frame * random(`${seed}-rotSpeed`) * 10;

  // Generate a random messy path
  const r = (id: string, min: number, max: number) =>
    interpolate(random(`${seed}-path-${id}`), [0, 1], [min, max]);

  const pathD = `M ${r("1", -30, 30)} ${r("2", -30, 30)} 
                 Q ${r("3", -50, 50)} ${r("4", -50, 50)} ${r("5", -30, 30)} ${r("6", -30, 30)} 
                 T ${r("7", -40, 40)} ${r("8", -40, 40)}
                 T ${r("9", -20, 20)} ${r("10", -20, 20)}`;

  return (
    <div
      style={{
        position: "absolute",
        left: "50%",
        top: "50%",
        transform: `translate(-50%, -50%) translate(${x}px, ${y}px) rotate(${rot}deg) scale(${scale})`,
        width: 100,
        height: 100,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <svg
        viewBox="-60 -60 120 120"
        style={{ width: "100%", height: "100%", overflow: "visible" }}
      >
        <path
          d={pathD}
          fill="none"
          stroke={color}
          strokeWidth={6}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </div>
  );
};

const ManifestoPoster: React.FC<ManifestoPosterProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 6,
  topText = "TAKE THE CHAOS.",
  bottomText = "GIVE IT DIRECTION.",
  primaryTextColor = "#ffffff",
  arrowColor = "#d94f04",
  accentColor = "#ccff00",
  logoColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- TIMING CONFIG ---
  const text1Start = 5;
  const chaosStart = 20;
  const convergeStart = 60;
  const arrowStart = 75;
  const text2Start = 90;
  const logoStart = 110;

  // --- ANIMATION CALCULATIONS ---

  // Top Text
  const topTextSpr = spring({
    frame: frame - text1Start,
    fps,
    config: { damping: 14, mass: 1.5 },
  });
  const topTextScale = interpolate(topTextSpr, [0, 1], [3, 1]);
  const topTextOpacity = interpolate(topTextSpr, [0, 0.5, 1], [0, 1, 1]);

  // Chaos & Convergence
  const chaosOpacity = interpolate(
    frame,
    [chaosStart, chaosStart + 10, convergeStart + 15, convergeStart + 20],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const convergenceProgress = interpolate(
    frame,
    [convergeStart, convergeStart + 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Arrow
  const arrowSpr = spring({
    frame: frame - arrowStart,
    fps,
    config: { damping: 12, mass: 1, stiffness: 120 },
  });
  const arrowY = interpolate(arrowSpr, [0, 1], [-300, 0]);
  const arrowScaleY = interpolate(arrowSpr, [0, 1], [0, 1]);
  const arrowOpacity = interpolate(arrowSpr, [0, 0.2], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Bottom Text
  const bottomTextSpr = spring({
    frame: frame - text2Start,
    fps,
    config: { damping: 12 },
  });
  const bottomTextY = interpolate(bottomTextSpr, [0, 1], [100, 0]);
  const bottomTextOpacity = interpolate(bottomTextSpr, [0, 1], [0, 1]);

  // Logo
  const logoOpacity = interpolate(
    frame,
    [logoStart, logoStart + 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Array of 60 scribbles
  const scribbles = Array.from({ length: 60 }).map((_, i) => i);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "8% 5%",
        boxSizing: "border-box",
      }}
    >
      {/* TOP TEXT */}
      <div
        style={{
          width: "100%",
          textAlign: "center",
          marginTop: "10%",
          transform: `scale(${topTextScale})`,
          opacity: topTextOpacity,
          transformOrigin: "top center",
        }}
      >
        <h1
          style={{
            fontSize: width * 0.18,
            color: primaryTextColor,
            margin: 0,
            lineHeight: 0.9,
            letterSpacing: "0.02em",
            textTransform: "uppercase",
          }}
        >
          {topText}
        </h1>
      </div>

      {/* METAPHOR CONTAINER (MIDDLE) */}
      <div
        style={{
          flex: 1,
          width: "100%",
          position: "relative",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* Chaos Scribbles */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            opacity: chaosOpacity,
          }}
        >
          {scribbles.map((i) => (
            <Scribble
              key={i}
              index={i}
              frame={frame}
              fps={fps}
              progress={convergenceProgress}
              color={arrowColor}
            />
          ))}
        </div>

        {/* Clean Downward Arrow */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            opacity: arrowOpacity,
          }}
        >
          <svg
            viewBox="0 0 100 400"
            style={{
              height: height * 0.4,
              transform: `translateY(${arrowY}px) scaleY(${arrowScaleY})`,
              transformOrigin: "top center",
              overflow: "visible",
            }}
          >
            {/* Arrow Stem */}
            <line
              x1="50"
              y1="0"
              x2="50"
              y2="360"
              stroke={arrowColor}
              strokeWidth="24"
              strokeLinecap="square"
            />
            {/* Arrow Head */}
            <path
              d="M 10 300 L 50 380 L 90 300"
              fill="none"
              stroke={arrowColor}
              strokeWidth="24"
              strokeLinecap="square"
              strokeLinejoin="miter"
            />
          </svg>
        </div>
      </div>

      {/* BOTTOM TEXT */}
      <div
        style={{
          width: "100%",
          textAlign: "center",
          marginBottom: "10%",
          transform: `translateY(${bottomTextY}px)`,
          opacity: bottomTextOpacity,
        }}
      >
        <h2
          style={{
            fontSize: width * 0.15,
            color: accentColor,
            margin: 0,
            lineHeight: 1,
            letterSpacing: "0.05em",
            textTransform: "uppercase",
          }}
        >
          {bottomText}
        </h2>
      </div>

      {/* MINIMALIST MONKEY LOGO */}
      <div
        style={{
          opacity: logoOpacity,
          marginBottom: "5%",
        }}
      >
        <svg
          width={width * 0.08}
          height={width * 0.08}
          viewBox="0 0 100 100"
          style={{ display: "block" }}
        >
          {/* Ears */}
          <circle cx="15" cy="50" r="18" fill={logoColor} />
          <circle cx="85" cy="50" r="18" fill={logoColor} />
          {/* Main Head */}
          <circle cx="50" cy="50" r="40" fill={logoColor} />
          {/* Face Cutout to imply snout/brow in a minimalist way */}
          <path
            d="M 25 45 Q 50 70 75 45 Q 50 15 25 45 Z"
            fill={backgroundColor}
          />
          {/* Eyes (Subtle) */}
          <circle cx="35" cy="40" r="4" fill={logoColor} />
          <circle cx="65" cy="40" r="4" fill={logoColor} />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default ManifestoPoster;